ctx.lineWidth = 2;

// Constants
const G = 9.8; // acceleration due to gravity (m/s^2)
const M = 1; // mass of the pendulum (kg)
const L = 0.5; // length of the pendulum (m)
const dt = 0.01; // time step (s)

// Initial conditions
let theta = radiansToDegrees(parseFloat(initAngleInput.value));
let omega = 0;

// Update and draw the pendulum
function updateAndDraw() {
  // Update the pendulum's state
  omega += (-G * Math.sin(theta) / L) * dt;
  theta += omega * dt;

  // Draw the pendulum
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.beginPath();
  ctx.arc(canvas.width / 2, canvas.height / 2, L, 0, 2 * Math.PI);
  ctx.fillStyle = 'black';
  ctx.fill();
  ctx.beginPath();
  ctx.arc(canvas.width / 2 + L * Math.sin(theta), canvas.height / 2 - L * Math.cos(theta), 5, 0, 2 * Math.PI);
  ctx.fillStyle = 'red';
  ctx.fill();

  // Check if the pendulum has stopped
  if (Math.abs(omega) < 0.01) {
